<template><section class="admin-page"><header class="admin-page__heading"><p class="admin-page__eyebrow">内容工作台</p><h1>文章与随笔</h1><RouterLink class="admin-button" :to="{name:'admin-article-new'}">新建内容</RouterLink></header><form class="admin-card filters" @change="apply"><label>状态<select v-model="status"><option value="">全部</option><option v-for="s in statuses" :key="s" :value="s">{{s}}</option></select></label><label>类型<select v-model="contentType"><option value="">全部</option><option value="ARTICLE">文章</option><option value="NOTE">随笔</option></select></label></form><p v-if="loading">正在加载…</p><p v-else-if="error" role="alert">{{error}}</p><div v-else class="admin-card table-wrap"><table><thead><tr><th>标题</th><th>类型</th><th>状态</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="a in pageData.items" :key="a.id"><td>{{a.title}}</td><td>{{a.contentType}}</td><td>{{a.status}}</td><td>{{a.publishedAt??a.scheduledAt??'—'}}</td><td><RouterLink :to="{name:'admin-article-edit',params:{id:a.id}}">编辑</RouterLink></td></tr></tbody></table><nav aria-label="文章分页"><button :disabled="page===0" @click="go(page-1)">上一页</button><span>第 {{page+1}} / {{Math.max(1,pageData.totalPages)}} 页</span><button :disabled="page+1>=pageData.totalPages" @click="go(page+1)">下一页</button></nav></div></section></template>
<script setup lang="ts">import {onMounted,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import type {ArticleStatus,AdminArticleSummaryResponse,PageResponse} from '../../../shared/api/contracts';import {listAdminArticles} from '../admin-api';const route=useRoute(),router=useRouter(),statuses=['DRAFT','SCHEDULED','PUBLISHED','ARCHIVED'];const page=ref(Number(route.query.page)||0),status=ref(String(route.query.status??'')),contentType=ref(String(route.query.contentType??'')),loading=ref(false),error=ref(''),pageData=ref<PageResponse<AdminArticleSummaryResponse>>({items:[],page:0,size:20,total:0,totalPages:0});async function load(){loading.value=true;try{pageData.value=await listAdminArticles({page:page.value,size:20,status:status.value as ArticleStatus||undefined,contentType:contentType.value||undefined})}catch{error.value='内容列表加载失败'}finally{loading.value=false}}function sync(){page.value=Number(route.query.page)||0;status.value=String(route.query.status??'');contentType.value=String(route.query.contentType??'');void load()}function apply(){void router.push({query:{page:0,status:status.value||undefined,contentType:contentType.value||undefined}})}function go(p:number){void router.push({query:{...route.query,page:p}})}watch(()=>route.query,sync,{deep:true});onMounted(load);</script>
<style scoped>.filters{display:flex;gap:20px;flex-wrap:wrap}.filters label{display:grid;gap:6px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #e4ddd6;text-align:left}nav{display:flex;justify-content:center;gap:16px;margin-top:20px}</style>
